const supportStaleSending = `-- name: SupportStaleSending :many
UPDATE support_message SET status='unknown',reason='worker_interrupted',updated_at=$1 WHERE status='sending' AND updated_at<$2 RETURNING id
`

type SupportStaleSendingParams struct {
	UpdatedAt   time.Time
	UpdatedAt_2 time.Time
}

func (q *Queries) SupportStaleSending(ctx context.Context, arg SupportStaleSendingParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, supportStaleSending, arg.UpdatedAt, arg.UpdatedAt_2)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const supportTotal = `-- name: SupportTotal :one
SELECT count(*) FROM support_conversation c WHERE ($1::text='' OR c.status=$1)
 AND (NOT $2::boolean OR c.assignee_id=$3::uuid)
 AND (NOT $4::boolean OR (c.status='open' AND c.last_incoming>c.answered_through))
 AND ($5::text='' OR c.name ILIKE '%'||$5||'%' OR c.username ILIKE '%'||$5||'%' OR c.max_user_id=$5)
`

type SupportTotalParams struct {
	Status     string
	Mine       bool
	ActorID    uuid.UUID
	NeedsReply bool
	Query      string
}

func (q *Queries) SupportTotal(ctx context.Context, arg SupportTotalParams) (int64, error) {
	row := q.db.QueryRow(ctx, supportTotal,
		arg.Status,
		arg.Mine,
		arg.ActorID,
		arg.NeedsReply,
		arg.Query,
	)
	var count int64
	err := row.Scan(&count)
	return count, err
}

